    ctx.fillRect(x, baseY - barH, barW, barH);
    ctx.strokeStyle = ink(7 / (5 * 4));
    ctx.strokeRect(x, baseY - barH, barW, barH);
    ctx.fillStyle = ink(4 / 5);
    ctx.font = `${labelPx}px monospace`;
    ctx.fillText(`|${amp.basis}\u27E9`, x, baseY + 7 * 2);
