  const stationOf = base.stationOf;
  const routed = exportNames.map((name2) => {
    const station = stationOf(name2);
    const entry2 = math.lookup[station];
    return {
      export: name2,
      station,
      order: entry2.order,
      path: stationPathFromSequence(entry2),
      folder: entry2.folder,
      fusion: entry2.fusion
    };
  });
  const byStation = math.digits.map((entry2) => ({
    digit: entry2.digit,
    path: stationPathFromSequence(entry2),
    folder: entry2.folder,
    exports: routed.filter((row) => row.station === entry2.digit).map((row) => row.export)
  }));
  const orphans = routed.filter((row) => !math.lookup[row.station]).length;
  const stationsUsed = new Set(routed.map((row) => row.station)).size;
