function calligraphyStroke2(seed, samples = 16 * 3) {
  const at = (tag) => seedFromText(`calligraphy:${seed}:${tag}`);
  const penAngle = (5 * 3 + at("pen") % (6 * 5 * 2)) * (TAU / 2 / (9 * 5 * 4));
  const nib = 9 + at("nib") % 7;
  const minRatio = 7 / (5 * 5 * 2);
  const ctl = (tag, lo, hi) => lo + at(tag) % (100 * 5 * 2) / (100 * 5 * 2) * (hi - lo);
  const cx = [ctl("x0", 16, 16 * 2), ctl("x1", 6 * 5, 6 * 5 * 2), ctl("x2", 16 * 3, 78), ctl("x3", 68, 88)];
  const cy = [ctl("y0", 7 * 4, 9 * 8), ctl("y1", 7 * 2, 52), ctl("y2", 52, 9 * 5 * 2), ctl("y3", 6 * 5, 9 * 8)];
  const bez = (t, a) => {
    const u = 1 - t;
    return u * u * u * a[0] + 3 * u * u * t * a[1] + 3 * u * t * t * a[2] + t * t * t * a[3];
  };
  const left = [];
  const right = [];
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    const x = bez(t, cx);
    const y = bez(t, cy);
    const tx = bez(min(1, t + 1 / (100 * 5 * 2)), cx) - bez(max(0, t - 1 / (100 * 5 * 2)), cx);
    const ty = bez(min(1, t + 1 / (100 * 5 * 2)), cy) - bez(max(0, t - 1 / (100 * 5 * 2)), cy);
    const theta = atan2(ty, tx);
    const half = nib / 2 * (minRatio + (1 - minRatio) * abs(sin(theta - penAngle)));
    const nx = cos(theta + TAU / 4);
    const ny = sin(theta + TAU / 4);
    left.push(`${round((x + nx * half) * (5 * 2)) / (5 * 2)} ${round((y + ny * half) * (5 * 2)) / (5 * 2)}`);
    right.push(`${round((x - nx * half) * (5 * 2)) / (5 * 2)} ${round((y - ny * half) * (5 * 2)) / (5 * 2)}`);
  }
  return {
    d: `M ${left.join(" L ")} L ${right.reverse().join(" L ")} Z`,
    penAngleDeg: round(penAngle * (9 * 5 * 4) / (TAU / 2)),
    nib,
    hue: at("hue") % 360,
    receipt: toUuid(`calligraphy-stroke:${seed}`)
  };
}
